// Checks that relative links in the project's knowledge docs point at files that exist.
// External (http/mailto) links and pure #anchors are not checked.
//
//   bun tools/agents/check-links.ts
import { existsSync, readdirSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { Glob } from "bun";

const root = resolve(import.meta.dir, "../..");
const patterns = [
  "*.md",
  "docs/**/*.md",
  "openspec/**/*.md",
  ".agents/skills/**/*.md",
  "crates/*/AGENTS.md",
  "crates/*/README.md",
];
// Generated by `openspec update`; their example links are placeholders.
const skip = [/^\.agents\/skills\/openspec-/];

// [text](target) and [text]: target — ignores images' data URIs and code spans well enough for docs.
const linkRe = /\[[^\]]*\]\(([^)\s]+)(?:\s+"[^"]*")?\)|^\s*\[[^\]]+\]:\s*(\S+)/gm;
const codeRe = /```[\s\S]*?```|`[^`\n]*`/g;

// Links into a submodule that is not checked out can't be checked locally; CI checks out all of them.
const gitmodules = existsSync(join(root, ".gitmodules")) ? await Bun.file(join(root, ".gitmodules")).text() : "";
const absentSubmodules = [...gitmodules.matchAll(/^\s*path\s*=\s*(.+)$/gm)]
  .map((m) => resolve(root, m[1].trim()))
  .filter((dir) => !existsSync(dir) || readdirSync(dir).length === 0);

let broken = 0;
let checked = 0;
const seen = new Set<string>();

for (const pattern of patterns) {
  for (const file of new Glob(pattern).scanSync({ cwd: root, dot: true })) {
    const rel = file.replaceAll("\\", "/");
    if (seen.has(rel) || skip.some((re) => re.test(rel))) continue;
    seen.add(rel);
    const text = (await Bun.file(join(root, rel)).text()).replace(codeRe, "");
    for (const m of text.matchAll(linkRe)) {
      const raw = m[1] ?? m[2];
      if (!raw || /^[a-z][a-z0-9+.-]*:/i.test(raw) || raw.startsWith("#") || raw.startsWith("<")) continue;
      const target = decodeURIComponent(raw.split("#")[0]);
      if (!target) continue;
      const abs = target.startsWith("/") ? join(root, target) : resolve(dirname(join(root, rel)), target);
      if (absentSubmodules.some((dir) => abs.startsWith(dir))) continue;
      checked++;
      if (!existsSync(abs) || (target.endsWith("/") && !statSync(abs).isDirectory())) {
        console.error(`${rel}: broken link -> ${raw} (${relative(root, abs).replaceAll("\\", "/")})`);
        broken++;
      }
    }
  }
}

console.log(`checked ${checked} relative links in ${seen.size} files, ${broken} broken`);
process.exit(broken ? 1 : 0);
